pub(crate) async fn list_thread_ids(&self) -> Vec<ThreadId> {
    self.threads
        .read()
        .await
        .iter()
        .filter_map(|(thread_id, thread)| {
            (!thread.session_source.is_internal()).then_some(*thread_id)
        })
        .collect()
}
